// High School course unit (docs/design/COURSES.md, docs/design/COURSE_QUALITY.md): English 10, Unit 3, Research and Citation.
// Our own wording and questions, written to the named national standards the course follows: the Common Core State Standards
// for English Language Arts, Writing and Speaking and Listening, grades 9-10. English 9 teaches research on short projects; English 10
// goes deeper, so every skill here is a move in a real research project: asking a researchable question and narrowing or broadening
// it (W.9-10.7), gathering from several authoritative print and digital sources, judging how useful each is, joining the information
// into one's own writing selectively, avoiding plagiarism and following a standard citation format (W.9-10.8), drawing evidence from
// texts by quoting, paraphrasing and summarizing (W.9-10.9), and integrating several sources while judging credibility and accuracy
// (SL.9-10.2). The citation style taught is MLA, 9th edition; APA is mentioned only as another style.
// Every source, author, journal, website, book and quotation in this unit is FICTIONAL and written for it (no real text is quoted, so
// nothing is copyrighted), and every prompt that uses one says so. Italic type is shown in words, as [italic: ...], because the game
// shows plain text. The MLA entries are built by one formatter below from the fictional source records; wrong choices are the common
// slips (first name first, titles marked the wrong way, an APA-style entry, a comma or a "p." in the citation).
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Video pictures: figure coordinates use a 100 x 34 sketch, north/up. Flow arrows trace before labels appear. */
const sketch=(title,regions,notes=[])=>{const pts={},polys=[];regions.forEach(([label,xy,col=0],i)=>{const v=xy.map(([x,y],k)=>{const n=String.fromCharCode(65+k)+i;pts[n]=[x,y];return n;}).join('');polys.push({v,label,col});});return {t:'figure',title,view:[0,100,0,34],pts,polys,notes:notes.map(([x,y,text])=>({at:[x,y],text})),dots:'',hide:Object.keys(pts).join('')};};
const flow=(title,stages)=>{const q=sketch(title,stages.map(([label],i)=>[label,[[i*36,13],[i*36+28,13],[i*36+28,25],[i*36,25]],i]),stages.map(([,detail],i)=>[i*36+14,7,detail]));q.segs=[];for(let i=0;i<2;i++){q.pts['P'+i]=[i*36+29,19];q.pts['Q'+i]=[i*36+35,19];q.segs.push({v:`P${i}Q${i}`,arrows:1,col:i,w:2});}q.hide=Object.keys(q.pts).join('');return q;};
const board=(title,lines,why)=>({t:'board',title,lines,...(why?{why}:{})});
const pass=(title,texts,small=true)=>({t:'passages',title,texts,...(small?{small:true}:{})});
const L='ABCDEF';
const dot=o=>o.replace(/\.$/,'');
const choose=(right,wrong,k)=>{right=dot(right);const opts=wrong.map(dot);opts.splice(k%(wrong.length+1),0,right);return {text:opts.map((o,i)=>`${L[i]}: ${o}`).join(', '),letter:L[opts.indexOf(right)],n:opts.length};};
/* citation choices keep their own final punctuation, so they are joined with a bar */
const chooseBar=(right,wrong,k)=>{const opts=[...wrong];opts.splice(k%(wrong.length+1),0,right);return {text:opts.map((o,i)=>`${L[i]}: ${o}`).join(' | '),letter:L[opts.indexOf(right)],n:opts.length};};
const ask=n=>n===2?'Answer A or B.':n===3?'Answer A, B or C.':`Answer ${[...L.slice(0,n-1)].join(', ')} or ${L[n-1]}.`;
const FIC='Fictional passage';
/* MLA 9 formatter for the fictional source records. A record: kind, au (surname, first), t title, c container, pub, vol, no, y, d, m, pp, pg, url. */
const MON=['','Jan.','Feb.','Mar.','Apr.','May','June','July','Aug.','Sept.','Oct.','Nov.','Dec.'];
const ital=t=>`[italic: ${t}]`;
