const authors=s=>{const a=s.au;return a.length===1?`${a[0][0]}, ${a[0][1]}`:a.length===2?`${a[0][0]}, ${a[0][1]}, and ${a[1][1]} ${a[1][0]}`:`${a[0][0]}, ${a[0][1]}, et al.`;};
const authorsFirst=s=>{const a=s.au||[['Calder Harbor','Office']];return a.length===1?(s.au?`${a[0][1]} ${a[0][0]}`:'Calder Harbor Office'):a.length===2?`${a[0][1]} ${a[0][0]} and ${a[1][1]} ${a[1][0]}`:`${a[0][1]} ${a[0][0]}, ${a[1][1]} ${a[1][0]}, and ${a[2][1]} ${a[2][0]}`;};
const endDot=x=>/\.$/.test(x)?x:x+'.';
const date=s=>`${s.d} ${MON[s.m]} ${s.y}`;
/* mode: 'ok' (the correct MLA 9 entry), 'first' (author first name first), 'swap' (the title marks swapped), 'apa' (an APA-style entry) */
const entry=(s,mode='ok')=>{
 const art=mode==='swap'?t=>`${ital(t)}.`:t=>`“${t}.”`, big=mode==='swap'?t=>`“${t}”`:ital;
 const au=s.au?(mode==='first'?authorsFirst(s):authors(s)):mode==='first'?'Calder Harbor Office':null, A=au?endDot(au)+' ':'';
 if(mode==='apa'){const who=s.au?s.au.map(([l,f],i)=>`${l}, ${f[0]}.`).join(' '):'';
  if(s.kind==='book')return `${who} (${s.y}). ${s.t}. ${s.pub}.`;
  if(s.kind==='article')return `${who} (${s.y}). ${s.t}. ${s.c}, ${s.vol}(${s.no}), ${s.pp}.`;
  if(s.kind==='news')return `${who} (${s.y}, ${MON[s.m].replace('.','')} ${s.d}). ${s.t}. ${s.c}, ${s.pg}.`;
  if(s.kind==='web')return `${who} (${s.y}, ${MON[s.m].replace('.','')} ${s.d}). ${s.t}. ${s.c}. ${s.url}`;
  return `${s.t}. (${s.y}, ${MON[s.m].replace('.','')} ${s.d}). ${s.c}. ${s.url}`;}
 if(s.kind==='book')return mode==='swap'?`${A}“${s.t}.” ${s.pub}, ${s.y}.`:`${A}${ital(s.t)}. ${s.pub}, ${s.y}.`;
 if(s.kind==='article')return `${A}${art(s.t)} ${big(s.c)}, vol. ${s.vol}, no. ${s.no}, ${s.y}, pp. ${s.pp}.`;
 if(s.kind==='news')return `${A}${art(s.t)} ${big(s.c)}, ${date(s)}, p. ${s.pg}.`;
 if(s.kind==='web')return `${A}${art(s.t)} ${big(s.c)}, ${date(s)}, ${s.url}.`;
 return `${A}${art(s.t)} ${big(s.c)}, ${s.pub}, ${date(s)}, ${s.url}.`;};
const who=s=>!s.au?`“${s.short}”`:s.au.length===1?s.au[0][0]:s.au.length===2?`${s.au[0][0]} and ${s.au[1][0]}`:`${s.au[0][0]} et al.`;
const cite=s=>s.page?`(${who(s)} ${s.page})`:`(${who(s)})`;
const citeWrong=s=>{const w=who(s);return s.page?[`(${w}, p. ${s.page})`,`(${w} ${s.y})`,`(${w}, ${s.page})`]:s.au?[`(${w}, ${s.y})`,`(${s.au[0][1]} ${w})`,`(${w}, p. 1)`]:[`(${s.short})`,`(${s.pub})`,`(“${s.short}”, ${s.y})`];};
