const ORDERS=[['Raman, Priya','Lind, Marcus','“Tide Tables for Calder Bay”'],['Whitcombe, Dana','Kim, Soo','Hollis, Greta'],['Okafor, Lena','“The Harbor Map”','Armitage, Joel']];
const sortKey=s=>s.replace(/^[“"]/,'').replace(/^(A|An|The) /i,'').toLowerCase();
const TRY=['Fictional research question: “What is the history of bridges?” Which is the best revision for a five-page paper? A: How did the building of three bridges across the fictional Calder River change trade in the town between 1900 and 1950, B: What is the history of all bridges and tunnels, C: What color is the Calder Bridge. Answer A, B or C.',
 'Fictional website: a page called Sea Facts Now has no author and sells supplements. Which step is lateral reading? A: Open a new tab and search for the group behind the site to see what independent sources say, B: Read the page’s About section twice, C: Count how many pages the site has. Answer A, B or C.',
 'Fictional source: a book by Ada Fenn titled The Quiet Lamp, published by Pine Ridge Press in 2016. A student quotes page 88. Which in-text citation is correct in MLA 9? A: (Fenn 88), B: (Fenn, p. 88), C: (Fenn 2016). Answer A, B or C.'];
