export default {
id:'language-h-english-10-research-and-citation',subject:'language',level:5,grade:9,standard:'CCSS ELA Writing W.9-10.7, 9-10.8 and 9-10.9, with Speaking and Listening SL.9-10.2; citations in MLA 9th edition',
title:'Research and Citation',
goal:'Run a research project: write a focused research question and narrow or broaden it, tell primary from secondary sources, judge credibility by author, publisher, date, purpose, evidence and lateral reading, join several sources by quoting, paraphrasing and summarizing with signal phrases, avoid plagiarism including patchwriting, and cite sources in MLA 9th edition.',
points:20,
skills:{inquiry:'Research questions and the inquiry',sources:'Primary and secondary sources and credibility',integrate:'Quoting, paraphrasing and summarizing',plagiarism:'Avoiding plagiarism',mla:'MLA 9 citations'},
outline:[['W.9-10.7','Conduct short and sustained research projects to answer a question, narrowing or broadening the inquiry when appropriate and synthesizing multiple sources',['inquiry']],['W.9-10.8','Gather information from multiple authoritative print and digital sources, assess usefulness, integrate it selectively, avoid plagiarism and follow a standard citation format (MLA 9)',['sources','plagiarism','mla']],['W.9-10.9','Draw evidence from literary or informational texts to support analysis, reflection and research',['integrate']],['SL.9-10.2','Integrate multiple sources in diverse formats, evaluating the credibility and accuracy of each',['sources']]],
steps:[
 {skill:'inquiry',say:'Research starts with a question, not a topic. A short project may answer one focused question from two or three sources in a day; a sustained project runs for weeks and may change direction. Either way the steps repeat: ask, gather, judge the sources, write, and then go back to the question if the evidence points somewhere new.',pic:flow('A research project',[['Ask','A focused question'],['Gather and judge','Several sources, checked'],['Write and cite','Claim, evidence, credit']])},
 {skill:'inquiry',say:'A good research question is neither too broad nor too narrow. Too broad, and no paper can cover it. Too narrow, and one fact answers it. Just right asks how or why, names a place, a time or an aspect, and needs evidence from several sources. The questions in the table are fictional examples.',pic:tab('Three fictional questions about a harbor town',[['Too broad: What is the history of harbors?','covers every harbor in every era'],['Too narrow: What day did the Calder ferry first sail?','one date answers it'],['Just right: How did the ferry change shopping in Calder between 1950 and 1970?','a place, a period, a change to explain']],['Why'])},
 {skill:'inquiry',say:'Narrow or broaden the inquiry as the evidence demands. If a search returns millions of results, narrow by place, time or one aspect. If almost nothing turns up, broaden the period or look at a related group. A narrowed question is not a failure; it is how a writer gets to a question that sources can answer.',pic:board('Narrowing a fictional topic',['Topic: ferries','Add a place: ferries in Calder','Add a time: Calder ferries, 1950-1970','Ask: how did they change shopping?'],['too broad','narrower','narrower still','a researchable question']),
  check:{prompt:tryIt(TRY[0]),answer:'A',options:['A','B','C'],hint:'A good question names a place and time, and asks how or why. Which one does that?',pic:pass('Fictional revision',['A: How did the building of three bridges across the fictional Calder River change trade in the town between 1900 and 1950?','B: What is the history of all bridges and tunnels?','C: What color is the Calder Bridge?'])}},
 {skill:'sources',say:'A primary source is a firsthand record from the time or person studied: a diary, a letter, a photograph, an interview you conduct, raw data. A secondary source interprets or reports on events at a later time: a textbook, a review article, a historian’s book. Which one a source is depends on the question being asked.',pic:tab('Primary and secondary (fictional examples)',[['A harbor pilot’s diary, 1902','primary'],['A photograph taken on the dock, 1902','primary'],['A textbook chapter written in 2020 about 1902','secondary'],['A review article summarizing thirty studies','secondary']],['Kind'])},
 {skill:'sources',say:'Judge every source before you use it. Ask who the author is and what makes this person knowledgeable, who published it and whether anyone checked it, when it appeared and whether that matters for the topic, why it was made, and what evidence it gives that you can check. No one question settles it; the answers together tell you how far to trust a source.',pic:tab('Credibility checks',[['Author','What expertise does this person have on the topic?'],['Publisher','Who published it, and does anyone review the work?'],['Date','Is it current enough for this topic?'],['Purpose','To inform, to persuade or to sell?'],['Evidence','Does it name sources and data a reader can check?']],['Ask'])},
 {skill:'sources',say:'Lateral reading checks a source by leaving it. Instead of studying a page that vouches for itself, open new tabs and search what other sources say about the author or group behind it. Then look for corroboration: independent sources that reach the same finding. Two articles that copy one press release are one source, not two.',pic:flow('Lateral reading',[['Leave the page','Open new tabs'],['Check others','Who is behind it?'],['Return','Decide how far to trust it']]),
  check:{prompt:tryIt(TRY[1]),answer:'A',options:['A','B','C'],hint:'Lateral reading means leaving the page. Which choice does that?',pic:pass('Fictional website',['Sea Facts Now has no author and sells supplements.'])}},
 {skill:'sources',say:'Often sources disagree, or arrive in different formats such as a chart, an interview and a video. Do not hide the difference. Compare the dates, the methods and the aim of each, ask which is better supported, and say so. In a presentation, report both and explain which you trust and why. Check a figure by tracing it back to where it came from.',pic:{t:'chart',kind:'bars',title:'Fictional sources disagree: reef area (sq km)',bars:[{label:'2012 brochure',value:40},{label:'2023 survey',value:55}]}},
 {skill:'integrate',say:'There are three ways to use a source. A quotation copies the exact words inside quotation marks, and is best when the wording is striking or precise. A paraphrase restates the whole idea in new words and structure, and fits when meaning matters more than wording. A summary gives only the main idea of a longer passage. All three need a citation.',pic:tab('Three ways to use a source',[['Quotation','exact words, in quotation marks'],['Paraphrase','the full idea, new words and structure'],['Summary','the main idea only, much shorter']],['How it looks'])},
 {skill:'integrate',say:'A signal phrase tells the reader whose words or ideas follow. Choose its verb with care: argues and concludes suit a claim, reports and finds suit data, and admits suggests a concession. A word such as claims can hint at doubt. Then follow the quotation with your own explanation, so that the evidence does its job in your paragraph.',pic:board('Lead in, quote, explain',['Ward (fictional) argues that','“towns grow where water is calm.”','So calm harbors drew builders.'],['signal phrase','quotation','explanation'])},
 {skill:'integrate',say:'Shape a quotation without changing its meaning. An ellipsis, three dots, shows that you left words out. Brackets show a word you changed or added to fit your sentence. A quotation of more than four lines of prose becomes a block quotation, indented half an inch with no quotation marks. In every case, keep the author’s meaning and choose only what supports your claim.',pic:tab('Shaping a quotation',[['Ellipsis (...)','words omitted'],['Brackets [ ]','a word changed or added'],['Block quotation','more than four lines; indented half an inch; no quotation marks']],['Use'])},
 {skill:'plagiarism',say:'Plagiarism is presenting another person’s words or ideas as your own. It happens with copied sentences and also with paraphrases that have no credit. Patchwriting is a quieter form: copying a source’s sentence and changing a few words. A real paraphrase is built from your understanding, in new words and structure, and it is still cited.',pic:pass('Fictional original and a patchwritten copy',['Original: The ferry carried shoppers across the river each morning.','Patchwritten: The ferry took buyers over the river every morning.']),
  },
 {skill:'plagiarism',say:'To avoid plagiarism, take careful notes. Put quotation marks around any exact words, write the source and page beside every note, and cite ideas as well as quotations. Facts that most people know and can easily check are common knowledge, such as the boiling point of water at sea level; a specific statistic or a theory needs credit. When in doubt, cite.',pic:flow('Safe note-taking',[['Mark','Quotation marks on exact words'],['Record','Source and page'],['Cite','Words and ideas']])},
 {skill:'mla',say:'This unit cites sources in MLA style, 9th edition, which is common in English and the humanities. APA is another style, used mainly in the social sciences, and it asks for different details. An MLA entry is built from core elements in a fixed order: Author, Title of source, Title of container, Publisher, Date and Location. Use the ones your source has.',pic:board('MLA 9 core elements, in order',['Author.','Title of source.','Title of container,','Publisher,','Date,','Location.'],['Last, First','article in quotation marks','journal or site, in italics','omit if it is the container','day Mon. year','pages or URL'])},
 {skill:'mla',say:'Here is a Works Cited entry for a fictional article. The title of the article is in quotation marks and the title of the journal, the container, is in italics (shown here in words, since the game shows plain text). The first line is flush left and the later lines have a half-inch hanging indent, and the whole list is in alphabetical order.',pic:pass('Fictional entry, MLA 9',['Voss, Hana. “Why Fog Forms Over Cold Bays.” [italic: Fictional Coastal Weather Review], vol. 4, no. 2, 2020, pp. 21-30.'])},
 {skill:'mla',say:'An in-text citation points the reader to the Works Cited entry. In MLA 9 it gives the author and the page, with no comma and no “p.”, as in (Voss 24). If the sentence already names the author, only the page goes in the parentheses. Two authors are joined with and, three or more use et al., a source with no author uses a shortened title, and a page with no page numbers uses just the author.',pic:tab('MLA 9 in-text citations (fictional source)',[['One author','(Voss 24)'],['Author named in the sentence','Voss argues that fog … (24).'],['Three or more authors','(Voss et al. 24)'],['No author','(“Fog Tables”)'],['No page numbers','(Voss)']],['Form']),
  check:{prompt:tryIt(TRY[2]),answer:'A',options:['A','B','C'],hint:'MLA gives the author and the page with no comma and no “p.”. Which choice does that?',pic:pass('Fictional source',['Ada Fenn, The Quiet Lamp (Pine Ridge Press, 2016), page 88.'])}},
 {skill:'mla',summary:true,say:'Tie the unit together with one habit: research as a loop. Ask a focused question and narrow or broaden it, find several sources and judge each by author, publisher, date, purpose, evidence and lateral reading, use them by quoting, paraphrasing or summarizing with a signal phrase, give credit every time, and cite in MLA 9 with a Works Cited page.',pic:flow('Research like a writer',[['Ask and gather','Question, sources'],['Judge and use','Credibility, quote, paraphrase'],['Credit','No plagiarism, MLA 9']])}],
progression:{requires:['language-h-english-10-rhetoric-in-nonfiction','language-h-english-9-reading-informational-texts'],operations:2,demand:'Run a research project: focused questions, primary and secondary sources, credibility and lateral reading, quoting, paraphrasing and summarizing with signal phrases, avoiding plagiarism, and MLA 9 citations.'},
items(add){
 const seen=new Set(TRY);
 const put=(skill,prompt,answer,pic,explanation,accept)=>{if(seen.has(prompt))return;seen.add(prompt);add(skill,prompt,answer,pic,explanation,accept);};
 ROWS.forEach(([skill,key,q,right,wrong,why],k)=>{
  if(skill==='plagiarism'&&key&&/patchwriting|acceptable paraphrase/.test(q)){const v=V[key],good=/patchwriting/.test(q),pr=good?v.patch:v.good,ws=good?[v.good,v.quote]:[v.patch,v.copy],c=choose(pr,ws,k);
   put(skill,`${P(key)[0]}: “${P(key)[1][0]}” ${q} ${c.text}. ${ask(c.n)}`,c.letter,pass(P(key)[0],[...P(key)[1],...c.text.split(/, (?=[A-F]: )/)]),why,[pr,dot(pr)]);return;}
  const c=choose(right,wrong,k);
  if(!key){put(skill,`${q} ${c.text}. ${ask(c.n)}`,c.letter,null/* 25 Oct: no picture; it only repeated the question in tiny type */,why,[right,dot(right)]);return;}
  const [src,lines,kind]=P(key);
  if(kind==='pair'){put(skill,`${src}. ${lines.join(' ')} ${q} ${c.text}. ${ask(c.n)}`,c.letter,pass(src,lines),why,[right,dot(right)]);return;}
  put(skill,`${src}: “${lines.join(' ')}” ${q} ${c.text}. ${ask(c.n)}`,c.letter,pass(src,lines),why,[right,dot(right)]);});
 SRC.forEach((s,k)=>{const wrongs=s.au?['first','swap','apa']:['first','swap','apa'],ws=[wrongs[k%3],wrongs[(k+1)%3]].map(m=>entry(s,m)),c=chooseBar(entry(s),ws,k+1);
  put('mla',`Fictional source: ${s.say}. Which is the correct MLA 9th edition Works Cited entry? ([italic: …] means italic type.) ${c.text} ${ask(c.n)}`,c.letter,pass('MLA 9 entry',[entry(s)]),'MLA 9 puts the author first, the article or page title in quotation marks, the book or container title in italics, then the other elements in order, with a period at the end.',[entry(s)]);
  const cw=citeWrong(s),cc=chooseBar(cite(s),[cw[k%3],cw[(k+1)%3]],k+2);
  put('mla',`Fictional source: ${s.say}. ${s.page?`A student quotes page ${s.page}.`:'A student paraphrases an idea from the page.'} Which is the correct MLA 9 in-text citation? ${cc.text} ${ask(cc.n)}`,cc.letter,null,'In MLA 9 the in-text citation gives the author (or a shortened title) and the page, with no comma and no “p.”; with no page number, only the author or title.',[cite(s)]);});
 SRC.filter(s=>s.au&&s.page).slice(0,4).forEach((s,k)=>{const nm=who(s),rt=`(${s.page})`,ws=[`(${nm} ${s.page})`,`(${s.y})`],c=chooseBar(rt,ws,k);
  put('mla',`Fictional source: ${s.say}. A sentence begins “According to ${nm}, …” and ends with a page citation from the source. Which closing citation is correct in MLA 9? ${c.text} ${ask(c.n)}`,c.letter,null,'When the sentence names the author, the parentheses hold only the page, because the name is already given.',[rt]);});
 ORDERS.forEach((names,k)=>{const label=n=>n.replace(/,.*$/,'').replace(/^“|”$/g,'').replace(/ for .*$/,''),by=f=>[...names].sort((x,y)=>f(x).localeCompare(f(y))).map(label).join(', '),rt=by(sortKey),cand=[...new Set([by(n=>label(n).toLowerCase()),names.map(label).join(', '),[...names].reverse().map(label).join(', '),by(sortKey).split(', ').reverse().join(', '),[names[1],names[2],names[0]].map(label).join(', ')])].filter(x=>x!==rt),c=chooseBar(rt,cand.slice(0,2),k);
  put('mla',`Fictional Works Cited entries begin with these words: ${names.join('; ')}. Which order is correct in MLA 9, alphabetized by the first word and ignoring A, An and The? ${c.text} ${ask(c.n)}`,c.letter,null,'Entries are alphabetized by their first word; a leading A, An or The is ignored, and a title-only entry is placed by its title.',[rt]);});
}};
